var subject=ctx.roles.subject,input=ctx.input,DEF='dnd2024.character.class-membership',KIND='character.has-class-membership';
function object(value){return value!==null&&!Array.isArray(value)&&typeof value==='object';}
function closed(value,keys){if(!object(value))return false;var actual=Object.keys(value).sort(),expected=keys.slice().sort();if(actual.length!==expected.length)return false;for(var i=0;i<expected.length;i++)if(actual[i]!==expected[i])return false;return true;}
function parse(raw){try{var value=JSON.parse(raw);if(!object(value))throw 0;return value;}catch(error){throw new Error('A class membership is malformed.');}}
if(!subject||!closed(input,[])||!Array.isArray(subject.related))throw new Error('Character-level derivation requires one subject and exactly empty input.');
if(subject.related.length===0)return {narration:subject.name+' has no recorded class membership.',effects:[],events:[],notifications:[],data:{test:'character-level-read',subjectId:subject.id,present:false,valid:false,problem:'absent',totalLevel:null,proficiencyBonus:null,membershipCount:0}};
var total=0,classes={},memberships={};for(var i=0;i<subject.related.length;i++){var related=subject.related[i];if(!closed(related,['components','data','fromEntityId','id','kind','name','toEntityId'])||related.kind!==KIND||related.fromEntityId!==subject.id||related.toEntityId!==related.id||related.data!=='{}'||memberships[related.id]||!closed(related.components,[DEF]))throw new Error('Character class-membership relationships are invalid.');memberships[related.id]=true;var membership=parse(related.components[DEF]),keys=Object.keys(membership).sort(),expected=Object.prototype.hasOwnProperty.call(membership,'subclassRef')?['classRef','level','subclassRef']:['classRef','level'];if(JSON.stringify(keys)!==JSON.stringify(expected)||!closed(membership.classRef,['entityId'])||typeof membership.classRef.entityId!=='string'||membership.classRef.entityId.indexOf('content.dnd2024.class.')!==0||!Number.isInteger(membership.level)||membership.level<1||membership.level>20||classes[membership.classRef.entityId]||(membership.subclassRef&&!closed(membership.subclassRef,['entityId'])))throw new Error('Character class-membership state is invalid.');classes[membership.classRef.entityId]=true;total+=membership.level;if(total>20)throw new Error('Total character level cannot exceed 20.');}
var bonus=2+Math.floor((total-1)/4);return {narration:subject.name+' is total level '+total+' with Proficiency Bonus +'+bonus+'.',effects:[],events:[],notifications:[],data:{test:'character-level-read',subjectId:subject.id,present:true,valid:true,problem:null,totalLevel:total,proficiencyBonus:bonus,membershipCount:subject.related.length}};
